1	// Package runtime implements the VM and runtime for FreeLang
2	package runtime
3	
4	import "fmt"
5	
6	// ValueKind represents the type of a value at runtime
7	type ValueKind int
8	
9	const (
10		KindNil ValueKind = iota
11		KindInt
12		KindBool
13		KindString
14		KindStruct
15		KindArray
16	)
17	
18	// Value represents a runtime value in FreeLang
19	type Value struct {
20		Kind   ValueKind
21		IVal   int64             // for KindInt
22		BVal   bool              // for KindBool
23		SVal   string            // for KindString
24		Fields map[string]Value  // for KindStruct (keys: "f0", "f1", ...)
25		Elems  []Value           // for KindArray
26	}
27	
28	// Constructors
29	func NilVal() Value {
30		return Value{Kind: KindNil}
31	}
32	
33	func IntVal(n int64) Value {
34		return Value{Kind: KindInt, IVal: n}
35	}
36	
37	func BoolVal(b bool) Value {
38		return Value{Kind: KindBool, BVal: b}
39	}
40	
41	func StringVal(s string) Value {
42		return Value{Kind: KindString, SVal: s}
43	}
44	
45	func StructVal() Value {
46		return Value{Kind: KindStruct, Fields: make(map[string]Value)}
47	}
48	
49	func ArrayVal(elems []Value) Value {
50		return Value{Kind: KindArray, Elems: elems}
51	}
52	
53	// Truthy returns whether a value is truthy in a conditional context
54	func (v Value) Truthy() bool {
55		switch v.Kind {
56		case KindNil:
57			return false
58		case KindBool:
59			return v.BVal
60		case KindInt:
61			return v.IVal != 0
62		case KindString:
63			return v.SVal != ""
64		case KindArray:
65			return len(v.Elems) > 0
66		case KindStruct:
67			return len(v.Fields) > 0
68		default:
69			return true
70		}
71	}
72	
73	// String returns a human-readable representation
74	func (v Value) String() string {
75		switch v.Kind {
76		case KindNil:
77			return "nil"
78		case KindInt:
79			return fmt.Sprintf("%d", v.IVal)
80		case KindBool:
81			return fmt.Sprintf("%v", v.BVal)
82		case KindString:
83			return fmt.Sprintf("%q", v.SVal)
84		case KindArray:
85			result := "["
86			for i, e := range v.Elems {
87				if i > 0 {
88					result += ", "
89				}
90				result += e.String()
91			}
92			result += "]"
93			return result
94		case KindStruct:
95			return fmt.Sprintf("struct{%d fields}", len(v.Fields))
96		default:
97			return "unknown"
98		}
99	}
100	
101	// ToInterface converts a Value to interface{} for builtin function calls
102	func (v Value) ToInterface() interface{} {
103		switch v.Kind {
104		case KindNil:
105			return nil
106		case KindInt:
107			return v.IVal
108		case KindBool:
109			return v.BVal
110		case KindString:
111			return v.SVal
112		case KindArray:
113			result := make([]interface{}, len(v.Elems))
114			for i, e := range v.Elems {
115				result[i] = e.ToInterface()
116			}
117			return result
118		case KindStruct:
119			return map[string]interface{}{"_type": "struct"}
120		default:
121			return nil
122		}
123	}
124	
125	// FromInterface creates a Value from interface{} (builtin return values)
126	func FromInterface(v interface{}) Value {
127		if v == nil {
128			return NilVal()
129		}
130	
131		switch val := v.(type) {
132		case int:
133			return IntVal(int64(val))
134		case int64:
135			return IntVal(val)
136		case bool:
137			return BoolVal(val)
138		case string:
139			return StringVal(val)
140		case []interface{}:
141			elems := make([]Value, len(val))
142			for i, e := range val {
143				elems[i] = FromInterface(e)
144			}
145			return ArrayVal(elems)
146		case []string:
147			elems := make([]Value, len(val))
148			for i, s := range val {
149				elems[i] = StringVal(s)
150			}
151			return ArrayVal(elems)
152		default:
153			return NilVal()
154		}
155	}
