1	// Package parser implements an AST parser for mini FreeLang
2	package parser
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/lexer"
9	)
10	
11	type Parser struct {
12		l         *lexer.Lexer
13		curToken  ast.Token
14		peekToken ast.Token
15	}
16	
17	// New creates a new parser for the input string
18	func New(input string) *Parser {
19		l := lexer.New(input)
20		p := &Parser{l: l}
21		p.nextToken()
22		p.nextToken()
23		return p
24	}
25	
26	func (p *Parser) nextToken() {
27		p.curToken = p.peekToken
28		p.peekToken = p.l.NextToken()
29	}
30	
31	// ParseProgram parses a complete program
32	func (p *Parser) ParseProgram() (*ast.Node, error) {
33		prog := &ast.Node{
34			Kind:     ast.NodeProgram,
35			Children: []*ast.Node{},
36		}
37	
38		for p.curToken.Type != ast.TokenEOF {
39			stmt, err := p.parseStatement()
40			if err != nil {
41				return nil, err
42			}
43			if stmt != nil {
44				prog.Children = append(prog.Children, stmt)
45			}
46			p.skipSemicolons()
47		}
48	
49		return prog, nil
50	}
51	
52	func (p *Parser) parseStatement() (*ast.Node, error) {
53		switch p.curToken.Type {
54		case ast.TokenLet:
55			return p.parseLetDecl()
56		case ast.TokenFn:
57			return p.parseFnDecl()
58		case ast.TokenIf:
59			return p.parseIfStmt()
60		case ast.TokenFor:
61			return p.parseForStmt()
62		case ast.TokenReturn:
63			return p.parseReturnStmt()
64		case ast.TokenStruct:
65			return p.parseStructDecl()
66		case ast.TokenLBrace:
67			return p.parseBlockStmt()
68		case ast.TokenSemicolon:
69			p.nextToken()
70			return nil, nil
71		default:
72			// Try to parse as expression statement
73			expr, err := p.parseExpression(0)
74			if err != nil {
75				return nil, err
76			}
77			return expr, nil
78		}
79	}
80	
81	func (p *Parser) parseLetDecl() (*ast.Node, error) {
82		letNode := &ast.Node{
83			Kind: ast.NodeLetDecl,
84			Line: p.curToken.Line,
85			Col:  p.curToken.Col,
86		}
87	
88		p.nextToken() // consume 'let'
89	
90		if p.curToken.Type != ast.TokenIdent {
91			return nil, fmt.Errorf("expected identifier after 'let'")
92		}
93	
94		nameNode := &ast.Node{
95			Kind:  ast.NodeIdent,
96			Value: p.curToken.Value,
97			Line:  p.curToken.Line,
98			Col:   p.curToken.Col,
99		}
100		letNode.Children = append(letNode.Children, nameNode)
101	
102		p.nextToken() // consume identifier
103	
104		// Check for type annotation: let x: int = ...
105		if p.curToken.Type == ast.TokenColon {
106			p.nextToken() // consume ':'
107			if p.curToken.Type != ast.TokenIdent {
108				return nil, fmt.Errorf("expected type name after ':'")
109			}
110			nameNode.TypeAnnotation = p.curToken.Value // "int", "bool", "Point", etc.
111			p.nextToken()                              // consume type name
112		}
113	
114		if p.curToken.Type != ast.TokenAssign {
115			return nil, fmt.Errorf("expected '=' after identifier")
116		}
117	
118		p.nextToken() // consume '='
119	
120		expr, err := p.parseExpression(0)
121		if err != nil {
122			return nil, err
123		}
124		letNode.Children = append(letNode.Children, expr)
125	
126		return letNode, nil
127	}
128	
129	func (p *Parser) parseFnDecl() (*ast.Node, error) {
130		fnNode := &ast.Node{
131			Kind: ast.NodeFnDecl,
132			Line: p.curToken.Line,
133			Col:  p.curToken.Col,
134		}
135	
136		p.nextToken() // consume 'fn'
137	
138		if p.curToken.Type != ast.TokenIdent {
139			return nil, fmt.Errorf("expected function name")
140		}
141	
142		fnNode.Value = p.curToken.Value
143		p.nextToken()
144	
145		if p.curToken.Type != ast.TokenLParen {
146			return nil, fmt.Errorf("expected '(' after function name")
147		}
148	
149		p.nextToken()
150	
151		// Parse parameters with type annotations
152		for p.curToken.Type != ast.TokenRParen {
153			if p.curToken.Type != ast.TokenIdent {
154				return nil, fmt.Errorf("expected parameter name")
155			}
156			param := &ast.Node{
157				Kind:  ast.NodeIdent,
158				Value: p.curToken.Value,
159			}
160			p.nextToken()
161	
162			// Parse parameter type annotation if present
163			if p.curToken.Type == ast.TokenColon {
164				p.nextToken()
165				if p.curToken.Type == ast.TokenIdent {
166					param.TypeAnnotation = p.curToken.Value // Store type annotation
167					p.nextToken()
168				}
169			}
170	
171			fnNode.Children = append(fnNode.Children, param)
172	
173			if p.curToken.Type == ast.TokenComma {
174				p.nextToken()
175			}
176		}
177	
178		p.nextToken() // consume ')'
179	
180		// Parse return type annotation if present: fn add(...): int
181		if p.curToken.Type == ast.TokenColon {
182			p.nextToken()
183			if p.curToken.Type == ast.TokenIdent {
184				fnNode.TypeAnnotation = p.curToken.Value // Store return type
185				p.nextToken()
186			}
187		}
188	
189		if p.curToken.Type != ast.TokenLBrace {
190			return nil, fmt.Errorf("expected '{' for function body")
191		}
192	
193		body, err := p.parseBlockStmt()
194		if err != nil {
195			return nil, err
196		}
197		fnNode.Children = append(fnNode.Children, body)
198	
199		return fnNode, nil
200	}
201	
202	func (p *Parser) parseIfStmt() (*ast.Node, error) {
203		ifNode := &ast.Node{
204			Kind: ast.NodeIfStmt,
205			Line: p.curToken.Line,
206			Col:  p.curToken.Col,
207		}
208	
209		p.nextToken() // consume 'if'
210	
211		cond, err := p.parseExpression(0)
212		if err != nil {
213			return nil, err
214		}
215		ifNode.Children = append(ifNode.Children, cond)
216	
217		if p.curToken.Type != ast.TokenLBrace {
218			return nil, fmt.Errorf("expected '{' after if condition")
219		}
220	
221		body, err := p.parseBlockStmt()
222		if err != nil {
223			return nil, err
224		}
225		ifNode.Children = append(ifNode.Children, body)
226	
227		// Check for else branch
228		if p.curToken.Type == ast.TokenElse {
229			p.nextToken() // consume 'else'
230	
231			if p.curToken.Type != ast.TokenLBrace {
232				return nil, fmt.Errorf("expected '{' after else")
233			}
234	
235			elseBody, err := p.parseBlockStmt()
236			if err != nil {
237				return nil, err
238			}
239			ifNode.Children = append(ifNode.Children, elseBody)
240		}
241	
242		return ifNode, nil
243	}
244	
245	func (p *Parser) parseForStmt() (*ast.Node, error) {
246		forNode := &ast.Node{
247			Kind: ast.NodeForStmt,
248			Line: p.curToken.Line,
249			Col:  p.curToken.Col,
250		}
251	
252		p.nextToken() // consume 'for'
253	
254		if p.curToken.Type != ast.TokenIdent {
255			return nil, fmt.Errorf("expected iterator variable")
256		}
257	
258		iter := &ast.Node{
259			Kind:  ast.NodeIdent,
260			Value: p.curToken.Value,
261		}
262		forNode.Children = append(forNode.Children, iter)
263		p.nextToken()
264	
265		if p.curToken.Type != ast.TokenIn {
266			return nil, fmt.Errorf("expected 'in' after iterator")
267		}
268	
269		p.nextToken()
270	
271		rng, err := p.parseExpression(0)
272		if err != nil {
273			return nil, err
274		}
275		forNode.Children = append(forNode.Children, rng)
276	
277		if p.curToken.Type != ast.TokenLBrace {
278			return nil, fmt.Errorf("expected '{' for loop body")
279		}
280	
281		body, err := p.parseBlockStmt()
282		if err != nil {
283			return nil, err
284		}
285		forNode.Children = append(forNode.Children, body)
286	
287		return forNode, nil
288	}
289	
290	func (p *Parser) parseReturnStmt() (*ast.Node, error) {
291		retNode := &ast.Node{
292			Kind: ast.NodeReturn,
293			Line: p.curToken.Line,
294			Col:  p.curToken.Col,
295		}
296	
297		p.nextToken() // consume 'return'
298	
299		if p.curToken.Type == ast.TokenSemicolon || p.curToken.Type == ast.TokenRBrace {
300			return retNode, nil
301		}
302	
303		expr, err := p.parseExpression(0)
304		if err != nil {
305			return nil, err
306		}
307		retNode.Children = append(retNode.Children, expr)
308	
309		return retNode, nil
310	}
311	
312	func (p *Parser) parseBlockStmt() (*ast.Node, error) {
313		block := &ast.Node{
314			Kind: ast.NodeBlockStmt,
315			Line: p.curToken.Line,
316			Col:  p.curToken.Col,
317		}
318	
319		p.nextToken() // consume '{'
320	
321		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
322			stmt, err := p.parseStatement()
323			if err != nil {
324				return nil, err
325			}
326			if stmt != nil {
327				block.Children = append(block.Children, stmt)
328			}
329			p.skipSemicolons()
330		}
331	
332		if p.curToken.Type != ast.TokenRBrace {
333			return nil, fmt.Errorf("expected '}'")
334		}
335	
336		p.nextToken() // consume '}'
337	
338		return block, nil
339	}
340	
341	func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
342		left, err := p.parsePrimary()
343		if err != nil {
344			return nil, err
345		}
346	
347		for prec < p.peekPrecedence() {
348			p.nextToken()
349			left, err = p.parseInfix(left)
350			if err != nil {
351				return nil, err
352			}
353		}
354	
355		return left, nil
356	}
357	
358	func (p *Parser) parsePrimary() (*ast.Node, error) {
359		switch p.curToken.Type {
360		case ast.TokenInt:
361			node := &ast.Node{
362				Kind:  ast.NodeIntLit,
363				Value: p.curToken.Value,
364				Line:  p.curToken.Line,
365				Col:   p.curToken.Col,
366			}
367			return node, nil
368	
369		case ast.TokenTrue:
370			node := &ast.Node{
371				Kind:  ast.NodeBoolLit,
372				Value: "true",
373				Line:  p.curToken.Line,
374				Col:   p.curToken.Col,
375			}
376			return node, nil
377	
378		case ast.TokenFalse:
379			node := &ast.Node{
380				Kind:  ast.NodeBoolLit,
381				Value: "false",
382				Line:  p.curToken.Line,
383				Col:   p.curToken.Col,
384			}
385			return node, nil
386	
387		case ast.TokenString:
388			node := &ast.Node{
389				Kind:  ast.NodeStringLit,
390				Value: p.curToken.Value,
391				Line:  p.curToken.Line,
392				Col:   p.curToken.Col,
393			}
394			return node, nil
395	
396		case ast.TokenIdent:
397			name := p.curToken.Value
398			node := &ast.Node{
399				Kind:  ast.NodeIdent,
400				Value: name,
401				Line:  p.curToken.Line,
402				Col:   p.curToken.Col,
403			}
404			// Check if next token is '{' for struct initialization
405			if p.peekToken.Type == ast.TokenLBrace {
406				p.nextToken() // move to '{'
407				return p.parseStructLit(name)
408			}
409			return node, nil
410	
411		case ast.TokenLParen:
412			p.nextToken()
413			expr, err := p.parseExpression(0)
414			if err != nil {
415				return nil, err
416			}
417			if p.curToken.Type != ast.TokenRParen {
418				return nil, fmt.Errorf("expected ')'")
419			}
420			return expr, nil
421	
422		default:
423			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
424		}
425	}
426	
427	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
428		// Handle field access: obj.field
429		if p.curToken.Type == ast.TokenDot {
430			p.nextToken() // consume '.'
431			if p.curToken.Type != ast.TokenIdent {
432				return nil, fmt.Errorf("expected field name after '.'")
433			}
434			return &ast.Node{
435				Kind:     ast.NodeFieldAccess,
436				Value:    p.curToken.Value,
437				Line:     p.curToken.Line,
438				Col:      p.curToken.Col,
439				Children: []*ast.Node{left},
440			}, nil
441		}
442	
443		node := &ast.Node{
444			Kind:     ast.NodeBinaryExpr,
445			Line:     p.curToken.Line,
446			Col:      p.curToken.Col,
447			Value:    p.curToken.Value,
448			Children: []*ast.Node{left},
449		}
450	
451		prec := p.curPrecedence()
452		p.nextToken()
453	
454		right, err := p.parseExpression(prec)
455		if err != nil {
456			return nil, err
457		}
458		node.Children = append(node.Children, right)
459	
460		// Handle function calls
461		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
462			call := &ast.Node{
463				Kind:  ast.NodeCallExpr,
464				Value: left.Value,
465			}
466			p.nextToken() // consume '('
467			for p.curToken.Type != ast.TokenRParen {
468				arg, err := p.parseExpression(0)
469				if err != nil {
470					return nil, err
471				}
472				call.Children = append(call.Children, arg)
473				if p.curToken.Type == ast.TokenComma {
474					p.nextToken()
475				}
476			}
477			p.nextToken() // consume ')'
478			return call, nil
479		}
480	
481		return node, nil
482	}
483	
484	func (p *Parser) peekPrecedence() int {
485		return precedence(p.peekToken.Type)
486	}
487	
488	func (p *Parser) curPrecedence() int {
489		return precedence(p.curToken.Type)
490	}
491	
492	func precedence(tok ast.TokenType) int {
493		switch tok {
494		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
495			return 1
496		case ast.TokenPlus, ast.TokenMinus:
497			return 2
498		case ast.TokenStar, ast.TokenSlash:
499			return 3
500		case ast.TokenDotDot:
501			return 4
502		case ast.TokenDot:
503			return 5
504		default:
505			return 0
506		}
507	}
508	
509	func (p *Parser) skipSemicolons() {
510		for p.curToken.Type == ast.TokenSemicolon {
511			p.nextToken()
512		}
513	}
514	
515	func (p *Parser) parseStructDecl() (*ast.Node, error) {
516		structNode := &ast.Node{
517			Kind: ast.NodeStructDecl,
518			Line: p.curToken.Line,
519			Col:  p.curToken.Col,
520		}
521	
522		p.nextToken() // consume 'struct'
523	
524		if p.curToken.Type != ast.TokenIdent {
525			return nil, fmt.Errorf("expected struct name")
526		}
527	
528		structNode.Value = p.curToken.Value
529		p.nextToken()
530	
531		if p.curToken.Type != ast.TokenLBrace {
532			return nil, fmt.Errorf("expected '{' after struct name")
533		}
534	
535		p.nextToken() // consume '{'
536	
537		// Parse fields
538		for p.curToken.Type != ast.TokenRBrace {
539			field, err := p.parseFieldDecl()
540			if err != nil {
541				return nil, err
542			}
543			structNode.Children = append(structNode.Children, field)
544	
545			if p.curToken.Type == ast.TokenSemicolon {
546				p.nextToken()
547			}
548		}
549	
550		p.nextToken() // consume '}'
551	
552		return structNode, nil
553	}
554	
555	func (p *Parser) parseFieldDecl() (*ast.Node, error) {
556		if p.curToken.Type != ast.TokenIdent {
557			return nil, fmt.Errorf("expected field name")
558		}
559	
560		fieldNode := &ast.Node{
561			Kind:  ast.NodeFieldDecl,
562			Value: p.curToken.Value,
563			Line:  p.curToken.Line,
564			Col:   p.curToken.Col,
565		}
566	
567		p.nextToken() // consume field name
568	
569		if p.curToken.Type != ast.TokenColon {
570			return nil, fmt.Errorf("expected ':' after field name")
571		}
572	
573		p.nextToken() // consume ':'
574	
575		if p.curToken.Type != ast.TokenIdent {
576			return nil, fmt.Errorf("expected field type")
577		}
578	
579		typeNode := &ast.Node{
580			Kind:  ast.NodeIdent,
581			Value: p.curToken.Value,
582			Line:  p.curToken.Line,
583			Col:   p.curToken.Col,
584		}
585		fieldNode.TypeAnnotation = p.curToken.Value // Store type annotation directly
586		fieldNode.Children = append(fieldNode.Children, typeNode)
587	
588		p.nextToken() // consume type
589	
590		return fieldNode, nil
591	}
