367	// genBinaryExpr generates IR for a binary expression
368	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
369		if len(node.Children) < 2 {
370			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
371		}
372	
373		left, err := g.genExpr(node.Children[0])
374		if err != nil {
375			return Operand{}, err
376		}
377	
378		right, err := g.genExpr(node.Children[1])
379		if err != nil {
380			return Operand{}, err
381		}
382	
383		result := g.newTemp()
384		op := g.opcodeFromOp(node.Value)
385	
386		g.emit(Instruction{
387			Op:   op,
388			Dest: result,
389			Src1: left,
390			Src2: right,
391		})
392	
393		return result, nil
394	}
