396	// genCallExpr generates IR for a function call
397	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
398		if len(node.Children) == 0 {
399			return Operand{}, fmt.Errorf("call expression requires function name")
400		}
401	
402		fnName := node.Children[0].Value
403	
404		// Special handling for syscall
405		if fnName == "syscall" {
406			if len(node.Children) < 2 {
407				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
408			}
409	
410			// syscall number (always first arg after function name)
411			numOp, err := g.genExpr(node.Children[1])
412			if err != nil {
413				return Operand{}, err
414			}
415	
416			// Additional args (starting from index 2)
417			for i := 2; i < len(node.Children); i++ {
418				argOp, err := g.genExpr(node.Children[i])
419				if err != nil {
420					return Operand{}, err
421				}
422				g.emit(Instruction{
423					Op:   OpParam,
424					Src1: argOp,
425				})
426			}
427	
428			// Emit syscall instruction
429			result := g.newTemp()
430			g.emit(Instruction{
431				Op:   OpSyscall,
432				Dest: result,
433				Src1: numOp,
434			})
435	
436			return result, nil
437		}
438	
439		// Emit parameters for regular function calls
440		for i := 1; i < len(node.Children); i++ {
441			argOp, err := g.genExpr(node.Children[i])
442			if err != nil {
443				return Operand{}, err
444			}
445			g.emit(Instruction{
446				Op:   OpParam,
447				Src1: argOp,
448			})
449		}
450	
451		// Emit call
452		result := g.newTemp()
453		g.emit(Instruction{
454			Op:   OpCall,
455			Dest: result,
456			Fn:   fnName,
457		})
458	
459		return result, nil
460	}
