487	func (g *Generator) opcodeFromOp(op string) Opcode {
488		switch op {
489		case "+":
490			return OpAdd
491		case "-":
492			return OpSub
493		case "*":
494			return OpMul
495		case "/":
496			return OpDiv
497		case "==":
498			return OpEq
499		case "!=":
500			return OpNe
501		case "<":
502			return OpLt
503		case ">":
504			return OpGt
505		case "<=":
506			return OpLe
507		case ">=":
508			return OpGe
509		default:
510			return OpNoop
511		}
512	}
