514	// genStructDecl generates IR for a struct declaration
515	func (g *Generator) genStructDecl(node *ast.Node) error {
516		if node.Value == "" {
517			return fmt.Errorf("struct declaration must have a name")
518		}
519	
520		name := node.Value
521		fields := []string{}
522	
523		// Extract field names from children
524		for _, field := range node.Children {
525			if field.Kind == ast.NodeFieldDecl {
526				fields = append(fields, field.Value)
527			}
528		}
529	
530		// Store struct definition
531		g.structFields[name] = fields
532	
533		// Calculate struct size (8 bytes per field)
534		size := len(fields) * 8
535	
536		// Save current function context
537		prevFn := g.currentFn
538		g.currentFn = nil // Emit to Main context
539	
540		// Emit OpStructDef instruction
541		g.emit(Instruction{
542			Op:   OpStructDef,
543			Fn:   name,
544			Src1: Operand{IsImm: true, ImmVal: int64(size)},
545		})
546	
547		// Restore function context
548		g.currentFn = prevFn
549	
550		return nil
551	}
