553	// genFieldAccess generates IR for a field access expression (obj.field)
554	func (g *Generator) genFieldAccess(node *ast.Node) (Operand, error) {
555		if len(node.Children) == 0 {
556			return Operand{}, fmt.Errorf("field access requires object expression")
557		}
558	
559		// Generate IR for object expression
560		objOp, err := g.genExpr(node.Children[0])
561		if err != nil {
562			return Operand{}, err
563		}
564	
565		fieldName := node.Value
566	
567		// Search for field offset in known structs
568		var offset int64
569		found := false
570		for _, fields := range g.structFields {
571			for i, f := range fields {
572				if f == fieldName {
573					offset = int64(i * 8)
574					found = true
575					break
576				}
577			}
578			if found {
579				break
580			}
581		}
582		// If not found, use offset 0 as fallback
583	
584		// Emit OpFieldLoad instruction
585		result := g.newTemp()
586		g.emit(Instruction{
587			Op:   OpFieldLoad,
588			Dest: result,
589			Src1: objOp,
590			Src2: Operand{IsImm: true, ImmVal: offset},
591		})
592	
593		return result, nil
594	}
